"""
Unit tests for ESM-2 embedding generation, disk artifact caching, and deterministic fallback.
"""
import numpy as np
import pytest
from services.embeddings import ESMEmbeddingService


def test_embedding_fallback_deterministic():
    service = ESMEmbeddingService(model_name="deterministic_test")
    service.using_fallback = True  # force deterministic path
    seq = ""

    emb1, meta1 = service.compute_embedding(seq, accession="TEST_DET_01", use_cache=False)
    assert isinstance(emb1, np.ndarray)
    assert len(emb1) == 320
    assert np.isclose(np.linalg.norm(emb1), 1.0, atol=1e-4)

    # Determinism check
    emb2, meta2 = service.compute_embedding(seq, accession="TEST_DET_01", use_cache=False)
    np.testing.assert_allclose(emb1, emb2)


def test_embedding_cache_disk_persistence(tmp_path):
    service = ESMEmbeddingService(embeddings_dir=tmp_path)
    service.using_fallback = True
    seq = "VAIKTLKPGTMSPEAFLQEAQVMKKLRHEKLVQLYAVVSEEPIYIV"

    # First call: computes and caches
    emb1, meta1 = service.compute_embedding(seq, accession="CACHE_TEST_01", use_cache=True)
    expected_file = service.get_embedding_path("CACHE_TEST_01")
    assert expected_file.exists()

    # Second call: loads from cache
    emb2, meta2 = service.compute_embedding(seq, accession="CACHE_TEST_01", use_cache=True)
    assert meta2["cached"] is True
    np.testing.assert_array_equal(emb1, emb2)
